request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
binary-006

Cluster Arity:
2

Cluster Members:
[
  {
    "name": "ACTION_IMPLEMENTS_PLANNED_STEP",
    "definition": "The action carries out a step that the reasoning explicitly specified as an intended future action or corrective step.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action performing the planned step."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node specifying the intended step, target, or corrective content."
      }
    ],
    "assertion_conditions": [
      "The reasoning specifies a future action, target, or corrective content.",
      "The action performs that specified step using a corresponding operation, target, or content."
    ],
    "exclusion_conditions": [
      "The action is unrelated to the reasoning's stated intent.",
      "The reasoning only describes an outcome or diagnosis without specifying an action.",
      "The action is an unplanned reaction that is not described in the reasoning."
    ]
  },
  {
    "name": "CONFIRMS_EXPECTED_OUTCOME_FROM_OBSERVATION",
    "definition": "The reasoning interprets an observation as confirming that an expected condition, success criterion, or intended outcome has been achieved.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node interpreting the observation as confirmation."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation providing evidence that matches the expected outcome."
      }
    ],
    "assertion_conditions": [
      "The reasoning states or implies an expected outcome or success criterion.",
      "The observation contains identifiable evidence matching that expectation.",
      "The reasoning explicitly treats the observation as confirmation that the expected outcome holds."
    ],
    "exclusion_conditions": [
      "The observation is used only as an input to further action rather than as confirmation.",
      "The reasoning merely predicts an outcome without checking it against an observation.",
      "The observation is ambiguous or unrelated to the expected condition."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws an explicit conclusion, diagnosis, or assessment that is supported by identifiable content of the observation.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node expressing the conclusion, diagnosis, or assessment."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying evidence for that conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion, diagnosis, or assessment beyond merely restating the observation.",
      "The conclusion depends on specific identifiable content of the observation, such as presence or absence of items, status, version, or output."
    ],
    "exclusion_conditions": [
      "The reasoning repeats or describes the observation without inferring anything from it.",
      "The observation is unrelated to the conclusion or contains no information that supports it.",
      "The conclusion rests only on prior knowledge with no identifiable evidential link to the observation."
    ]
  },
  {
    "name": "PREDICTS_OUTCOME_OF_PLANNED_OPERATION",
    "definition": "The reasoning forecasts a specific consequence of an operation it has not yet performed, deriving that forecast from identifiable state evidence reported in an observation.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node naming the planned operation and stating the predicted consequence."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying the state evidence on which the forecast rests."
      }
    ],
    "assertion_conditions": [
      "The reasoning names an operation that is planned but not yet performed.",
      "A specific expected consequence of that operation is stated, such as an anticipated conflict, failure, or produced change.",
      "The forecast is tied to identifiable state evidence in the observation."
    ],
    "exclusion_conditions": [
      "The reasoning describes an outcome that has already been observed.",
      "The forecast is speculation not connected to identifiable state evidence.",
      "No specific consequence is predicted.",
      "The observation content cited is unrelated to the predicted consequence."
    ]
  },
  {
    "name": "DERIVES_TRIGGER_CONDITION",
    "definition": "The reasoning derives, from structural evidence in an observation, a specific input or state condition whose satisfaction causes the target to take a particular behavior path or produce a particular outcome.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node stating the condition that controls the target's behavior path."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation whose structural content (code, configuration, layout, or data) supports the derived condition."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a specific, testable condition involving an input value, offset, argument, or state of the target.",
      "The reasoning indicates that satisfying the condition makes the target reach a particular behavior path or outcome rather than continuing on its default path.",
      "The condition is derived from identifiable structural content of the observation rather than asserted without support."
    ],
    "exclusion_conditions": [
      "The reasoning describes target behavior without identifying any condition that controls which path is taken.",
      "The stated condition is unrelated to the observation's content or is an unsupported guess.",
      "The reasoning only reports the target's general behavior or reproduces observed output without linking it to a controlling condition.",
      "The reasoning only explains how a behavior is implemented, without asserting an input or state condition that selects that behavior."
    ]
  }
]

Previously Generated Predicate Names:
["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE",
  "definition": "The reasoning establishes a specific, content-level connection between a specification it states or derives—such as an intended action step, an expected outcome or success criterion, a conclusion or diagnosis, the predicted consequence of a planned operation, or an input/state condition controlling behavior—and a second observed element. That observed element may be an action execution or an environmental/structural observation, and its operation, target, output, status, configuration, or data must specifically implement, confirm, support, or ground the reasoned specification. The relation is explicit and evidential or executable, not merely topical.",
  "parameters": [
    {
      "name": "reasoning",
      "type": "reasoning",
      "description": "The reasoning node that states or derives the specification, expectation, conclusion, prediction, or controlling condition and explicitly relates it to the observed element."
    },
    {
      "name": "observed_element",
      "type": "observation",
      "description": "The observation of an action execution or of environmental/structural state whose specific operation, target, result, status, configuration, or data content corresponds to and implements, confirms, supports, or grounds the reasoning's stated specification."
    }
  ],
  "assertion_conditions": [
    "The reasoning states a specific intended step, expected outcome or success criterion, conclusion or diagnosis, predicted consequence, or input/state condition that controls a target's behavior.",
    "The observation contains identifiable content from an action execution or environmental/structural state, such as an operation and target, outcome or status, configuration, or data, that corresponds to the reasoned specification.",
    "The reasoning explicitly uses that content as implementation of the planned step, confirmation of the expected outcome, evidential support for the conclusion, the state basis for the prediction, or the structural basis for the derived condition."
  ],
  "exclusion_conditions": [
    "The reasoning and observed element are only topically related and lack a specific matching operation, outcome, status, structural feature, or evidential content.",
    "The reasoning merely restates or describes the observed element without stating an intended step, expectation, conclusion, prediction, or controlling condition, or without drawing the correspondence.",
    "The reasoning states an intention, expectation, conclusion, prediction, or condition but the observed element supplies no specific corresponding content or evidence.",
    "The correspondence rests only on prior belief or speculation with no identifiable basis in the observed element.",
    "The observed element is used only as an incidental input for further action and not as implementation, confirmation, support, grounding, or derivation for the reasoned specification."
  ]
}

